BEGIN EXECUTE IMMEDIATE 'DROP TABLE CLIENTES'; EXCEPTION WHEN OTHERS THEN NULL; END;

CREATE TABLE CLIENTES (
    ID NUMBER(10),
    NOMBRE VARCHAR(100),
    APELLIDO VARCHAR(100),
    EMAIL VARCHAR(150),
    TELEFONO VARCHAR(30),
    RUT VARCHAR(25),
    FECHA_NACIMIENTO DATE,
    GENERO VARCHAR(10),
    ESTADO_CIVIL VARCHAR(20),
    DIRECCION_LINEA1 VARCHAR(200),
    DIRECCION_LINEA2 VARCHAR(100),
    CIUDAD VARCHAR(100),
    REGION VARCHAR(100),
    CODIGO_POSTAL VARCHAR(15),
    PAIS VARCHAR(50)
);

BEGIN EXECUTE IMMEDIATE 'DROP TABLE EMPLEADOS'; EXCEPTION WHEN OTHERS THEN NULL; END;

CREATE TABLE EMPLEADOS (
    ID NUMBER(10),
    NOMBRE VARCHAR(100),
    APELLIDO VARCHAR(100),
    EMAIL_CORPORATIVO VARCHAR(150),
    EMAIL_PERSONAL VARCHAR(150),
    TELEFONO VARCHAR(30),
    RUT VARCHAR(25),
    FECHA_NACIMIENTO DATE,
    CARGO VARCHAR(100),
    DEPARTAMENTO VARCHAR(100),
    SALARIO NUMBER(12,2),
    FECHA_INGRESO DATE,
    DIRECCION_LINEA1 VARCHAR(200),
    DIRECCION_LINEA2 VARCHAR(100),
    CIUDAD VARCHAR(100),
    CODIGO_POSTAL VARCHAR(15),
    BANCO VARCHAR(100),
    CUENTA_BANCARIA VARCHAR(30)
);

BEGIN EXECUTE IMMEDIATE 'DROP TABLE CUENTAS_BANCARIAS'; EXCEPTION WHEN OTHERS THEN NULL; END;

CREATE TABLE CUENTAS_BANCARIAS (
    ID NUMBER(10),
    NUMERO_CUENTA VARCHAR(30),
    SUCURSAL VARCHAR(10),
    TIPO_CUENTA VARCHAR(30),
    SALDO NUMBER(14,2),
    LIMITE NUMBER(14,2),
    TITULAR VARCHAR(200),
    RUT_TITULAR VARCHAR(25),
    BANCO VARCHAR(100),
    FECHA_APERTURA DATE,
    ESTADO VARCHAR(20)
);

BEGIN EXECUTE IMMEDIATE 'DROP TABLE TARJETAS_CREDITO'; EXCEPTION WHEN OTHERS THEN NULL; END;

CREATE TABLE TARJETAS_CREDITO (
    ID NUMBER(10),
    NUMERO_TARJETA VARCHAR(25),
