);

BEGIN EXECUTE IMMEDIATE 'DROP TABLE PEDIDOS'; EXCEPTION WHEN OTHERS THEN NULL; END;

CREATE TABLE PEDIDOS (
    ID NUMBER(10),
    NUMERO_PEDIDO VARCHAR(20),
    FECHA_PEDIDO DATE,
    NOMBRE_CLIENTE VARCHAR(200),
    RUT_CLIENTE VARCHAR(25),
